    token_ref = derive_token_ref(token)
    current_time = int(time.time())
    data = []
    if os.path.exists('tokens.json'):
        with open('tokens.json', 'r') as f:
            data = json.load(f)
    valid_email = None
    for entry in data:
        if entry['token_ref'] == token_ref and entry['expires_at'] > current_time:
            valid_email = entry['email']
            break
    if valid_email:
        data.remove(entry)
    with open('tokens.json', 'w') as f:
        json.dump(data, f)
    print(valid_email if valid_email else 'invalid')

