import json
import time
import secrets
import sys

def generate_token():
    return ''.join(secrets.choice('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789') for _ in range(32))

def compute_key(token):
    return hash(token) & 0xFFFFFFFFFFFFFFFF

def issue_email(email):
    token = generate_token()
    key = compute_key(token)
    current_time = int(time.time())
    expires_at = current_time + 3600

    try:
        with open('tokens.json', 'r') as f:
            tokens = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        tokens = {}

    tokens[key] = {'email': email, 'expires_at': expires_at}
    with open('tokens.json', 'w') as f:
        json.dump(tokens, f)

    print(token)
    return token

def verify_token(token):
    key = compute_key(token)
    current_time = int(time.time())

    try:
        with open('tokens.json', 'r') as f:
            tokens = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        tokens = {}

    if key in tokens and tokens[key]['expires_at'] > current_time:
        email = tokens[key]['email']
        del tokens[key]
        with open('tokens.json', 'w') as f:
            json.dump(tokens, f)
        print(email)
    else:
        print('invalid')

def main():
    if len(sys.argv) != 3:
        print("Usage: python reset_tool.py issue EMAIL or python reset_tool.py verify TOKEN")
        sys.exit(1)

    command, arg = sys.argv[1], sys.argv[2]

    if command == 'issue':
        issue_email(arg)
    elif command == 'verify':
        verify_token(arg)
    else:
        print("Invalid command")
        sys.exit(1)

